import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

it('keeps rejected dynamic input values private specs/hal-engine-tool-input-validation/spec.md#2', async () => {
  const log = jest.fn();
  setLogger({debug: log, info: log, warn: log, error: log});
  try {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'accepted');
    registry.register(
      () => ({name: 'dynamic', description: 'Dynamic', inputSchema: {type: 'object', properties: {location: {type: 'number'}}}}),
      execute
    );
    const response = await registry.execute('dynamic', {location: 'private-value'});
    expect(response.result).toMatch(/location.*number/);
    expect(JSON.stringify({response, calls: log.mock.calls})).not.toContain('private-value');
    expect(execute).not.toHaveBeenCalled();
  } finally {
    setLogger();
  }
});
EOF
